/** Shared constants for Haversack (formerly Project Runtime — ADR 002). */

/** Marker line inside every generated file; the basis of drift detection. */
export const GENERATED_HEADER_MARKER = "GENERATED BY HAVERSACK — DO NOT EDIT.";

/** Legacy marker from the Project Runtime era; still detected as "ours" so a
 *  v0.1.0 repo migrates cleanly instead of being orphaned (ADR 002 §3.2). */
export const LEGACY_GENERATED_HEADER_MARKER = "GENERATED BY RUNTIME — DO NOT EDIT.";

/** Per-line allowlist marker for secret scanning. A line containing it is skipped. */
export const ALLOW_SECRET_MARKER = "haversack:allow-secret";

/** Legacy allow marker (Project Runtime era) — honored indefinitely (ADR 002 §3.6). */
export const LEGACY_ALLOW_SECRET_MARKER = "runtime:allow-secret";

/** Drift manifest location, relative to the repo root. Committed to git. */
export const MANIFEST_REL_PATH = ".haversack/manifest.json";

/** Legacy manifest location (Project Runtime era) — adopted on read, removed
 *  after the first successful sync (ADR 002 §3.1). */
export const LEGACY_MANIFEST_REL_PATH = ".runtime/manifest.json";

/** `sync` warns when a generated file exceeds this size (import mode is planned for v1.1). */
export const SIZE_WARN_BYTES = 20 * 1024;

/** Cap for context/rules files inlined into the definition. */
export const MAX_SOURCE_FILE_BYTES = 128 * 1024;

/** Cap for files scanned by `haversack check`; larger files are skipped with a warning. */
export const CHECK_MAX_FILE_BYTES = 1024 * 1024;

/**
 * Cooperative per-check time budget for `haversack check` (M3): a static check
 * that exceeds it is `skipped` — never a hang, never a pass. Residual risk:
 * a single line that backtracks catastrophically inside one regex.test call
 * cannot be interrupted without worker threads (unsupported in Node SEA
 * builds); the 1 MB per-file input cap bounds that work.
 */
export const CHECK_TIME_BUDGET_MS = 1_000;
